mapper.select:
SELECT c.id, c.course_name, c.description, c.teacher_id, c.max_score, c.create_time, u.real_name AS teacher_name FROM course c LEFT JOIN sys_user u ON c.teacher_id = u.id AND u.is_deleted = 0 WHERE c.is_deleted = 0
AND c.course_name LIKE CONCAT('%', #{courseName}, '%')
ORDER BY c.id DESC LIMIT #{limit} OFFSET #{offset}
